input.new_string:
for f in sections/*.md; do
  # Part dividers, keyed to the deck's four parts. Emitted before their first section.
  case "$(basename "$f")" in
    01-*) printf '## Part 1 — Concept Buddy\n\n' >> "$out" ;;
    03-*) printf '## Part 2 — Working with an AI coding assistant\n\n' >> "$out" ;;
    06-*) printf '## Part 3 — Building an agent that works\n\n' >> "$out" ;;
    10-*) printf '## Part 4 — Framework-specific recommendations\n\n' >> "$out" ;;
  esac

  owner=$(sed -n 's/^owner: *//p' "$f" | head -1)
  body=$(sed '/^---$/,/^---$/d' "$f")
